// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {Context} from "swap-vm/src/libs/VM.sol";
import {Opcode} from "swap-vm/src/libs/OpcodeList.sol";
import {MemoryPtr, MemoryPtrLib} from "swap-vm/src/libs/MemoryPtr.sol";
import {InstructionBuilder} from "swap-vm/src/libs/InstructionBuilder.sol";
import {InstructionArgs} from "swap-vm/src/libs/InstructionArgs.sol";

/// @notice Caps the maker's token to a live share of the real wallet.
/// @dev Reserved conditions-bank slot Opcode._28.
///      Encoding: [address token][uint16 maxShareBps][address aqua]
///      `available = min(aquaVirtual, balanceOf(maker) * maxShareBps / 10_000, allowance(maker, aqua))`
///      Reverts `InsufficientWalletBalance` when available is zero.
library WalletGuard {
    using InstructionArgs for bytes;
    using InstructionBuilder for MemoryPtr;

    error InsufficientWalletBalance(uint256 available, uint256 needed);
    error MaxShareBpsOutOfRange(uint16 maxShareBps);

    Opcode internal constant opcode = Opcode._28;

    uint256 internal constant SHARE_DENOM = 10_000;

    function sizeOf(address, uint16, address) internal pure returns (uint256) {
        return InstructionBuilder.sizeOf() + 20 + 2 + 20;
    }

    function build(
        address token,
        uint16 maxShareBps,
        address aqua
    ) internal pure returns (bytes memory) {
        return
            build(
                MemoryPtrLib.alloc(sizeOf(token, maxShareBps, aqua)),
                token,
                maxShareBps,
                aqua
            ).resolve();
    }

    function build(
        MemoryPtr ptrStart,
        address token,
        uint16 maxShareBps,
        address aqua
    ) internal pure returns (MemoryPtr ptr) {
        require(maxShareBps <= SHARE_DENOM, MaxShareBpsOutOfRange(maxShareBps));
        ptr = ptrStart.pushHeader(opcode);
        ptr = ptr.push(token).push(maxShareBps, 2).push(aqua);
        ptrStart.patchLength(ptr);
    }

    function parse(
        bytes calldata args
    ) internal pure returns (address token, uint16 maxShareBps, address aqua) {
        token = args.at(0).asAddress();
        maxShareBps = args.at(20).asU16();
        aqua = args.at(22).asAddress();
    }

    function availableOf(
        address maker,
        address token,
        uint16 maxShareBps,
        address aqua,
        uint256 aquaVirtual
    ) internal view returns (uint256) {
        uint256 share = Math.mulDiv(
            IERC20(token).balanceOf(maker),
            maxShareBps,
            SHARE_DENOM
        );
        uint256 allowance_ = IERC20(token).allowance(maker, aqua);
        return Math.min(aquaVirtual, Math.min(share, allowance_));
    }

    function exec(Context memory ctx, bytes calldata args) internal view {
        (address token, uint16 maxShareBps, address aqua) = parse(args);
        if (token != ctx.query.tokenOut) return;

        uint256 available = availableOf(
            ctx.query.maker,
            token,
            maxShareBps,
            aqua,
            ctx.swap.balanceOut
        );
        if (available == 0)
            revert InsufficientWalletBalance(
                0,
                ctx.swap.amountOut == 0 ? 1 : ctx.swap.amountOut
            );
        if (available < ctx.swap.balanceOut) ctx.swap.balanceOut = available;
    }
}

src/instructions/CoverageGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IAqua } from "@1inch/aqua/src/interfaces/IAqua.sol";

import { Context } from "swap-vm/src/libs/VM.sol";
import { Opcode } from "swap-vm/src/libs/OpcodeList.sol";
import { MemoryPtr, MemoryPtrLib } from "swap-vm/src/libs/MemoryPtr.sol";
import { InstructionBuilder } from "swap-vm/src/libs/InstructionBuilder.sol";
import { InstructionArgs } from "swap-vm/src/libs/InstructionArgs.sol";

import { WalletGuard } from "./WalletGuard.sol";

/// @notice Auto-docks a quote when coverage falls below the maker's floor.
/// @dev Reserved conditions-bank slot Opcode._29.
///      Encoding: [uint16 minCoverageBps][uint16 maxShareBps][address aqua]
///      `quotedSize` is the live Aqua virtual balance.
///      `realAvailable = min(quotedSize, wallet × maxShareBps / 10_000, allowance)`
///      `coverage = realAvailable / quotedSize` in bps.
///      Reverts `CoverageBreach(coverage)` below `minCoverageBps`.
///      Reads Aqua virtual itself so it stays correct after WalletGuard caps `balanceOut`.
library CoverageGuard {
    using InstructionArgs for bytes;
    using InstructionBuilder for MemoryPtr;

    error CoverageBreach(uint256 coverage);
    error MinCoverageBpsOutOfRange(uint16 minCoverageBps);

    Opcode internal constant opcode = Opcode._29;

    uint256 internal constant BPS = 10_000;

    function sizeOf(uint16, uint16, address) internal pure returns (uint256) {
        return InstructionBuilder.sizeOf() + 2 + 2 + 20;
    }

    function build(uint16 minCoverageBps, uint16 maxShareBps, address aqua) internal pure returns (bytes memory) {
        return build(MemoryPtrLib.alloc(sizeOf(minCoverageBps, maxShareBps, aqua)), minCoverageBps, maxShareBps, aqua)
            .resolve();
    }

    function build(MemoryPtr ptrStart, uint16 minCoverageBps, uint16 maxShareBps, address aqua)
        internal
        pure
        returns (MemoryPtr ptr)
    {
        require(minCoverageBps > 0 && minCoverageBps <= BPS, MinCoverageBpsOutOfRange(minCoverageBps));
        ptr = ptrStart.pushHeader(opcode);
        ptr = ptr.push(minCoverageBps, 2).push(maxShareBps, 2).push(aqua);
        ptrStart.patchLength(ptr);
    }

    function parse(bytes calldata args)
        internal
        pure
        returns (uint16 minCoverageBps, uint16 maxShareBps, address aqua)
    {
        minCoverageBps = args.at(0).asU16();
        maxShareBps = args.at(2).asU16();
        aqua = args.at(4).asAddress();
    }

    function coverageOf(address maker, address token, uint16 maxShareBps, address aqua, uint256 quotedSize)
        internal
        view
        returns (uint256 coverageBps, uint256 realAvailable)
    {
        realAvailable = WalletGuard.availableOf(maker, token, maxShareBps, aqua, quotedSize);
        if (quotedSize == 0) return (0, realAvailable);
        coverageBps = Math.mulDiv(realAvailable, BPS, quotedSize);
    }

    function exec(Context memory ctx, bytes calldata args) internal view {
        (uint16 minCoverageBps, uint16 maxShareBps, address aqua) = parse(args);
        (uint248 quotedSize,) =
            IAqua(aqua).rawBalances(ctx.query.maker, address(this), ctx.query.orderHash, ctx.query.tokenOut);
        (uint256 coverage,) = coverageOf(ctx.query.maker, ctx.query.tokenOut, maxShareBps, aqua, uint256(quotedSize));
        if (coverage < minCoverageBps) revert CoverageBreach(coverage);
    }
}

src/instructions/RungQuote.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {Context} from "swap-vm/src/libs/VM.sol";
import {Opcode} from "swap-vm/src/libs/OpcodeList.sol";
import {MemoryPtr, MemoryPtrLib} from "swap-vm/src/libs/MemoryPtr.sol";
import {InstructionBuilder} from "swap-vm/src/libs/InstructionBuilder.sol";
import {InstructionArgs} from "swap-vm/src/libs/InstructionArgs.sol";

/// @notice Fixed-price two-sided quote. A rung is a price, not a curve.
/// @dev Swap-curve bank slot Opcode._52.
///      Encoding:
///        [uint256 level][uint256 halfSpread][uint256 bidCap][uint256 askCap]
///        [uint8 wethDecimals][uint8 quoteDecimals][uint8 flags]
///      `level` and `halfSpread` are 1e18 ETH/USD.
///      Bid (maker buys ETH) fills at `L − s`. Ask (maker sells ETH) fills at `L + s`.
///      flags bit0 = wethIsTokenA.
library RungQuote {
    using InstructionArgs for bytes;
    using InstructionBuilder for MemoryPtr;
    using Math for uint256;

    error SideOff();
    error ZeroPrice();
    error ZeroOutput();

    Opcode internal constant opcode = Opcode._52;

    uint256 internal constant ONE = 1e18;
    uint8 internal constant FLAG_WETH_IS_TOKEN_A = 1;

    function sizeOf(uint256, uint256, uint256, uint256, uint8, uint8, uint8) internal pure returns (uint256) {
        return InstructionBuilder.sizeOf() + 32 + 32 + 32 + 32 + 1 + 1 + 1;
    }

    function build(
        uint256 level,
        uint256 halfSpread,
        uint256 bidCap,
        uint256 askCap,
        uint8 wethDecimals,
        uint8 quoteDecimals,
        bool wethIsTokenA
    ) internal pure returns (bytes memory) {
        uint8 flags = wethIsTokenA ? FLAG_WETH_IS_TOKEN_A : 0;
        return build(
            MemoryPtrLib.alloc(sizeOf(level, halfSpread, bidCap, askCap, wethDecimals, quoteDecimals, flags)),
            level,
            halfSpread,
            bidCap,
            askCap,
            wethDecimals,
            quoteDecimals,
            flags
        ).resolve();
    }

    function build(
        MemoryPtr ptrStart,
        uint256 level,
        uint256 halfSpread,
        uint256 bidCap,
        uint256 askCap,
        uint8 wethDecimals,
        uint8 quoteDecimals,
        uint8 flags
    ) internal pure returns (MemoryPtr ptr) {
        ptr = ptrStart.pushHeader(opcode);
        ptr = ptr.push(level, 32).push(halfSpread, 32).push(bidCap, 32).push(askCap, 32).push(wethDecimals).push(
            quoteDecimals
        ).push(flags);
        ptrStart.patchLength(ptr);
    }

    function parse(bytes calldata args)
        internal
        pure
        returns (
            uint256 level,
            uint256 halfSpread,
            uint256 bidCap,
            uint256 askCap,
            uint8 wethDecimals,
            uint8 quoteDecimals,
            uint8 flags
        )
    {
        level = args.at(0).asU256();
        halfSpread = args.at(32).asU256();
        bidCap = args.at(64).asU256();
        askCap = args.at(96).asU256();
        wethDecimals = args.at(128).asU8();
        quoteDecimals = args.at(129).asU8();
        flags = args.at(130).asU8();
    }

    function exec(Context memory ctx, bytes calldata args) internal pure {
        (
            uint256 level,
            uint256 halfSpread,
            uint256 bidCap,
            uint256 askCap,
            uint8 wethDecimals,
            uint8 quoteDecimals,
            uint8 flags
        ) = parse(args);

        bool wethIsTokenA = (flags & FLAG_WETH_IS_TOKEN_A) != 0;
        bool aToB = ctx.query.tokenIn < ctx.query.tokenOut;
        bool takerSellsWeth = wethIsTokenA ? aToB : !aToB;
        // Taker selling WETH → maker bid. Taker buying WETH → maker ask.
        bool isBid = takerSellsWeth;

        uint256 price = isBid ? level - halfSpread : level + halfSpread;
        require(price > 0, ZeroPrice());

        uint256 sideCap = isBid ? bidCap : askCap;
        if (sideCap == 0) revert SideOff();

        uint256 maxOut = ctx.swap.balanceOut < sideCap ? ctx.swap.balanceOut : sideCap;
        if (maxOut == 0) revert SideOff();

        uint256 wethScale = 10 ** uint256(wethDecimals);
        uint256 quoteScale = 10 ** uint256(quoteDecimals);

        if (ctx.query.isExactIn) {
            uint256 amountOut = _outForIn(isBid, ctx.swap.amountIn, price, wethScale, quoteScale);
            if (amountOut > maxOut) {
                amountOut = maxOut;
                ctx.swap.amountIn = _inForOut(isBid, amountOut, price, wethScale, quoteScale);
            }
            ctx.swap.amountOut = amountOut;
        } else {
            uint256 amountOut = ctx.swap.amountOut > maxOut ? maxOut : ctx.swap.amountOut;
            ctx.swap.amountOut = amountOut;
            ctx.swap.amountIn = _inForOut(isBid, amountOut, price, wethScale, quoteScale);
        }

        require(ctx.swap.amountOut > 0 && ctx.swap.amountIn > 0, ZeroOutput());
    }

    /// @dev Bid: WETH in → USDC out at `price`. Ask: USDC in → WETH out at `price`.
    function _outForIn(bool isBid, uint256 amountIn, uint256 price, uint256 wethScale, uint256 quoteScale)
        private
        pure
        returns (uint256)
    {
        if (isBid) {
            return Math.mulDiv(amountIn, price * quoteScale, ONE * wethScale);
        }
        return Math.mulDiv(amountIn, ONE * wethScale, price * quoteScale);
    }

    function _inForOut(bool isBid, uint256 amountOut, uint256 price, uint256 wethScale, uint256 quoteScale)
        private
        pure
        returns (uint256)
    {
        if (isBid) {
            return Math.mulDiv(amountOut, ONE * wethScale, price * quoteScale, Math.Rounding.Ceil);
        }
        return Math.mulDiv(amountOut, price * quoteScale, ONE * wethScale, Math.Rounding.Ceil);
    }
}

